const crypto = require('node:crypto');
const path = require('node:path');
const { createRequire } = require('node:module');
const root = '/Users/kyle.mathews/programs/blygger-studio/.worktrees/oracles-explore';
const projectRequire = createRequire(path.join(root, 'package.json'));
const ts = projectRequire('typescript');
const playwright = projectRequire('playwright');
const sha = text => crypto.createHash('sha256').update(text).digest('hex');
const sourcePath = path.join(root, 'src/ui/format-shortcuts.ts');
const source = fs.readFileSync(sourcePath, 'utf8');
const compiled = ts.transpileModule(source, {compilerOptions:{target:ts.ScriptTarget.ES2022, module:ts.ModuleKind.CommonJS}}).outputText;
const shapes = [
  {name:'native-safe-insert', source:'ab', edit:{from:1,to:1,insert:'X',start:2,end:2}},
  {name:'inside-grapheme-insert', source:'a\u0301b', edit:{from:1,to:1,insert:'X',start:2,end:2}},
  {name:'native-safe-empty-noop', source:'ab', edit:{from:1,to:1,insert:'',start:1,end:1}},
];
const modes = ['actual-native', 'injected-false-without-mutation', 'injected-unavailable', 'injected-throw-before-mutation', 'injected-true-without-mutation'];
const result = {
  recordedAt:new Date().toISOString(),
  kind:'disposable-observational-probe-no-assertions',
  sourcePath, sourceSha256:sha(source), transpiledSha256:sha(compiled),
  typescriptVersion:ts.version, playwrightVersion:projectRequire('playwright/package.json').version,
  playwrightBrowsersPath:process.env.PLAYWRIGHT_BROWSERS_PATH ?? null,
  oraclePackageVersion:projectRequire('@tanstack/oracles/package.json').version,
  sourceDelivery:'unchanged source transpileModule ES2022/CommonJS, evaluated into isolated exports; no oracle mutation or application wrapper',
  scriptPath:__filename, scriptSha256:sha(fs.readFileSync(__filename)), script:fs.readFileSync(__filename,'utf8'),
  engines:[],
};
(async () => {
  for (const engine of ['chromium','firefox']) {
    let browser;
    const receipt = {engine, cases:[]}; result.engines.push(receipt);
    try {
      browser = await playwright[engine].launch({headless:true});
      receipt.version = browser.version();
      for (const shape of shapes) for (const mode of modes) {
        const page = await browser.newPage();
        try {
          await page.setContent('<!doctype html><meta charset="utf-8"><textarea id="editor"></textarea>');
          const observed = await page.evaluate(({compiled, shape, mode}) => {
            const exports = {}; new Function('exports', compiled)(exports);
            const sut = exports.applyEdit;
            const element = document.getElementById('editor');
            element.value = shape.source;
            element.setSelectionRange(0,0);
            const nativeCommand = document.execCommand;
            const ownDescriptor = Object.getOwnPropertyDescriptor(document,'execCommand');
            const protoDescriptor = Object.getOwnPropertyDescriptor(Document.prototype,'execCommand');
            const receipt = {
              mode,shape, userAgent:navigator.userAgent,
              availableHostType:typeof nativeCommand,
              availableHostFunction:typeof nativeCommand==='function' ? Function.prototype.toString.call(nativeCommand) : null,
              nativeCommandWasOwnProperty:!!ownDescriptor,
              prototypeDescriptor:protoDescriptor ? {writable:protoDescriptor.writable,configurable:protoDescriptor.configurable,enumerable:protoDescriptor.enumerable} : null,
              applyEditFunction:Function.prototype.toString.call(sut),
              moduleExportIsInvokedFunction:exports.applyEdit===sut,
              events:[], commands:[], fallbacks:[], timeline:[], errors:[],
            };
            const state = () => ({source:element.value,start:element.selectionStart,end:element.selectionEnd,direction:element.selectionDirection,focused:document.activeElement===element});
            receipt.before = state();
            const eventListener = event => {
              const item={type:event.type,target:event.target===element?'textarea':event.target===document?'document':event.target.tagName,
                isTrusted:event.isTrusted,bubbles:event.bubbles,inputType:event.inputType??null,data:event.data??null,defaultPrevented:event.defaultPrevented,state:state()};
              receipt.events.push(item); receipt.timeline.push({event:item});
            };
            document.addEventListener('beforeinput',eventListener,true);
            document.addEventListener('input',eventListener,true);
            document.addEventListener('selectionchange',eventListener,true);
            window.addEventListener('error', event => receipt.errors.push({kind:'error',message:event.message}));
            window.addEventListener('unhandledrejection',event=>receipt.errors.push({kind:'unhandledrejection',message:String(event.reason)}));
            const nativeRangeText = element.setRangeText;
            element.setRangeText = function(...args) {
              const entry={args,before:state(), delegatedToOriginalElementMethod:true};
              receipt.fallbacks.push(entry); receipt.timeline.push({fallback:entry});
              try {const value=Reflect.apply(nativeRangeText,this,args);entry.returnType=typeof value;return value;}
              catch(error){entry.throw={name:error.name,message:error.message};throw error;}
              finally{entry.after=state();}
            };
            if(mode==='injected-unavailable') Object.defineProperty(document,'execCommand',{configurable:true,writable:true,value:undefined});
            else Object.defineProperty(document,'execCommand',{configurable:true,writable:true,value:function(...args){
              const command={args,before:state(),hostMode:mode,delegatedToOriginalNative:mode==='actual-native',originalIdentityPreserved:nativeCommand===receiptNative};
              receipt.commands.push(command); receipt.timeline.push({command});
              try {
                let value;
                if(mode==='actual-native') value=Reflect.apply(nativeCommand,document,args);
                else if(mode==='injected-false-without-mutation') value=false;
                else if(mode==='injected-true-without-mutation') value=true;
                else throw new DOMException('Injected probe host failure before mutation','NotSupportedError');
                command.returned=value; return value;
              } catch(error){command.throw={name:error.name,message:error.message};throw error;}
              finally{command.after=state();}
            }});
            const receiptNative=nativeCommand;
            receipt.invokedHostType=typeof document.execCommand;
            receipt.hostInjection=mode!=='actual-native';
            receipt.realNativeRecordingWrapper=mode==='actual-native';
            try {const returned=sut(element,shape.edit);receipt.applyReturn={type:typeof returned,value:returned??null};}
            catch(error){receipt.applyThrow={name:error.name,message:error.message};}
            receipt.immediateAfter=state();
            window.__probeReceipt=receipt;
            window.__probeState=state;
            return {completed:true};
          },{compiled,shape,mode});
          if(!observed.completed) throw Error('probe did not finish');
          await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
          const snapshot = await page.evaluate(()=>({...window.__probeReceipt,settledAfter:window.__probeState()}));
          snapshot.applyEditFunctionSha256=sha(snapshot.applyEditFunction);
          receipt.cases.push(snapshot);
          console.log(JSON.stringify({engine,shape:shape.name,mode,commandReturn:snapshot.commands[0]?.returned??null,commandThrow:snapshot.commands[0]?.throw?.name??null,applyThrow:snapshot.applyThrow?.name??null,source:snapshot.immediateAfter.source,fallbackCount:snapshot.fallbacks.length}));
        } finally {await page.close();}
      }
    } catch(error){receipt.setupOrProbeFailure={name:error.name,message:error.message,stack:error.stack};console.log(JSON.stringify({engine,failure:receipt.setupOrProbeFailure}));}
    finally {if(browser) await browser.close();}
  }
  const destination=path.join(root,'docs/editor-oracle-design/native-command-host-probes.json');
  fs.writeFileSync(destination,JSON.stringify(result,null,2)+'\n');
  console.log(JSON.stringify({destination,sha256:sha(fs.readFileSync(destination)),caseCount:result.engines.reduce((n,e)=>n+e.cases.length,0)}));
})().catch(error=>{console.error(error);process.exitCode=1;});

